  final messages = <ToolResultMessage>[];
  for (final toolCall in toolCalls) {
    await emit(
      ToolExecutionStartEvent(
        toolCallId: toolCall.id,
        toolName: toolCall.name,
        args: toolCall.arguments,
        timestamp: DateTime.now(),
