        'Re-issue the tool call with complete arguments.',
      ),
      true,
    );
    await _emitToolExecutionEnd(finalized, emit);
    messages.add(await _emitToolResultMessage(finalized, emit));
  }
  return _ExecutedToolCallBatch(messages, terminate: false);
}

