        // The relieved transcript becomes the loop's live context:
        // the retried request is built from it and every later turn
        // rides it (the tuple return hands it back to the host).
        return (
          context: Context(
            systemPrompt: context.systemPrompt,
            messages: relieved,
            tools: context.tools,
          ),
          reliefUsed: true,
          retried: true,
          terminal: null,
        );
      }
