  final bool wireDump;
  final OverWindowRelief? overWindowRelief;
  final ToolMisuseBreaker? toolMisuseBreaker;

  const AgentWiringSpec({
    required this.model,
    required this.systemPrompt,
    this.maxEmptyRetries = 1,
    this.onRunIdleTimeout,
    this.onRunWatchdogPaused,
